fn unobserved_wide_status_construction_uses_the_same_authenticated_held_bound() {
    let prefix = "shared.".repeat(146);
    let names = (0..16_000)
        .map(|index| format!("{prefix}.{index:06}"))
        .collect::<Vec<_>>();
